WHERE p.TE_NOME IN ('FUNCTION_LIST', 'FUNCTION_DETAIL')
  AND f.TE_NOME = 'FUNCTION_INQUIRY'
  AND NOT EXISTS (SELECT 1 FROM ${database.defaultSchemaName}.AUTH_FUN_AUTH_PERM x WHERE x.CO_AUTH_PERMISSION_ID = p.CO_ID AND x.CO_AUTH_FUNCTION_ID = f.CO_ID);

-- Abilitazione delle funzioni Auth ai gruppi amministrativi.
INSERT INTO ${database.defaultSchemaName}.AUTH_GROUP_AUTH_FUNC (CO_AUTH_FUNCTION_ID, CO_AUTH_GROUP_ID)
SELECT f.CO_ID, g.CO_ID FROM ${database.defaultSchemaName}.AUTH_FUNCTION f, ${database.defaultSchemaName}.AUTH_GROUP g
WHERE f.TE_NOME IN ('PERMISSION_MANAGEMENT', 'PERMISSION_INQUIRY', 'GROUP_MANAGEMENT', 'GROUP_INQUIRY', 'USER_MANAGEMENT', 'USER_INQUIRY', 'FUNCTION_MANAGEMENT', 'FUNCTION_INQUIRY')
  AND g.TE_NOME IN ('pagopa-u-adgroup-smo-kpi-psp-amministrativa', 'pagopa-u-adgroup-smo-payments-amministrativa', 'pagopa-u-adgroup-smo-kpi-prn-amministrativa')
  AND NOT EXISTS (SELECT 1 FROM ${database.defaultSchemaName}.AUTH_GROUP_AUTH_FUNC x WHERE x.CO_AUTH_FUNCTION_ID = f.CO_ID AND x.CO_AUTH_GROUP_ID = g.CO_ID);

